export function assertReportCommit(v){check(oid(v),'full lowercase commit/tree identity');return v;}
export const reportSha256=b=>createHash('sha256').update(b).digest('hex');
export function reportCanonicalSha256(v){assertReportPlainJson(v);return reportSha256(Buffer.from(canonical(v)));}
